examples:
统一初始化：
unordered_map<int, string> m {
    {1, "Item 1"},
    {2, "Item 2"},
    {3, "Item 3"},
    {4, "Item 4"}
};

使用结构化绑定：
for (const auto& [key, value] : m) {
    cout << format("{} = {}", key, value) << endl;
}

不使用结构化绑定：
for (const auto& p : m) {
    cout << format("{} = {}", p.first, p.second) << endl;
}
